   717  static void read_metadata_timecode(struct aom_read_bit_buffer *rb) {
   718    aom_rb_read_literal(rb, 5);  // counting_type f(5)
   719    const int full_timestamp_flag =
   720        aom_rb_read_bit(rb);     // full_timestamp_flag f(1)
