   722    aom_rb_read_bit(rb);         // cnt_dropped_flag f(1)
   723    aom_rb_read_literal(rb, 9);  // n_frames f(9)
   724    if (full_timestamp_flag) {
   725      aom_rb_read_literal(rb, 6);  // seconds_value f(6)
   726      aom_rb_read_literal(rb, 6);  // minutes_value f(6)
   727      aom_rb_read_literal(rb, 5);  // hours_value f(5)
   728    } else {
   729      const int seconds_flag = aom_rb_read_bit(rb);  // seconds_flag f(1)
   730      if (seconds_flag) {
   731        aom_rb_read_literal(rb, 6);                    // seconds_value f(6)
   732        const int minutes_flag = aom_rb_read_bit(rb);  // minutes_flag f(1)
   733        if (minutes_flag) {
   734          aom_rb_read_literal(rb, 6);                  // minutes_value f(6)
   735          const int hours_flag = aom_rb_read_bit(rb);  // hours_flag f(1)
   736          if (hours_flag) {
   737            aom_rb_read_literal(rb, 5);  // hours_value f(5)
   738          }
   739        }
   740      }
   741    }
   742    // time_offset_length f(5)
   743    const int time_offset_length = aom_rb_read_literal(rb, 5);
   744    if (time_offset_length) {
   745      // time_offset_value f(time_offset_length)
   746      aom_rb_read_literal(rb, time_offset_length);
   747    }
   748  }
