   750  // Returns the last nonzero byte in 'data'. If there is no nonzero byte in
   751  // 'data', returns 0.
   752  //
   753  // Call this function to check the following requirement in the spec:
   754  //   This implies that when any payload data is present for this OBU type, at
   755  //   least one byte of the payload data (including the trailing bit) shall not
   756  //   be equal to 0.
   757  static uint8_t get_last_nonzero_byte(const uint8_t *data, size_t sz) {
   758    // Scan backward and return on the first nonzero byte.
   759    size_t i = sz;
   760    while (i != 0) {
   761      --i;
   762      if (data[i] != 0) return data[i];
   763    }
   764    return 0;
   765  }
