   767  // Checks the metadata for correct syntax but ignores the parsed metadata.
   768  //
   769  // On success, returns the number of bytes read from 'data'. On failure, sets
   770  // pbi->common.error.error_code and returns 0, or calls aom_internal_error()
   771  // and does not return.
   772  static size_t read_metadata(AV1Decoder *pbi, const uint8_t *data, size_t sz) {
   773    AV1_COMMON *const cm = &pbi->common;
   774    size_t type_length;
   775    uint64_t type_value;
   776    if (aom_uleb_decode(data, sz, &type_value, &type_length) < 0) {
   777      cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   778      return 0;
   779    }
   780    const OBU_METADATA_TYPE metadata_type = (OBU_METADATA_TYPE)type_value;
   781    if (metadata_type == 0 || metadata_type >= 6) {
   782      // If metadata_type is reserved for future use or a user private value,
   783      // ignore the entire OBU and just check trailing bits.
   784      if (get_last_nonzero_byte(data + type_length, sz - type_length) == 0) {
   785        cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   786        return 0;
   787      }
   788      return sz;
   789    }
   790    if (metadata_type == OBU_METADATA_TYPE_ITUT_T35) {
   791      // read_metadata_itut_t35() checks trailing bits.
   792      read_metadata_itut_t35(pbi, data + type_length, sz - type_length);
   793      return sz;
   794    } else if (metadata_type == OBU_METADATA_TYPE_HDR_CLL) {
   795      size_t bytes_read =
   796          type_length +
   797          read_metadata_hdr_cll(pbi, data + type_length, sz - type_length);
   798      if (get_last_nonzero_byte(data + bytes_read, sz - bytes_read) != 0x80) {
   799        cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   800        return 0;
   801      }
   802      return sz;
   803    } else if (metadata_type == OBU_METADATA_TYPE_HDR_MDCV) {
   804      size_t bytes_read =
   805          type_length +
   806          read_metadata_hdr_mdcv(pbi, data + type_length, sz - type_length);
   807      if (get_last_nonzero_byte(data + bytes_read, sz - bytes_read) != 0x80) {
   808        cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   809        return 0;
   810      }
   811      return sz;
   812    }
   813
   814    struct aom_read_bit_buffer rb;
   815    av1_init_read_bit_buffer(pbi, &rb, data + type_length, data + sz);
   816    if (metadata_type == OBU_METADATA_TYPE_SCALABILITY) {
   817      read_metadata_scalability(&rb);
   818    } else {
   819      assert(metadata_type == OBU_METADATA_TYPE_TIMECODE);
   820      read_metadata_timecode(&rb);
   821    }
   822    if (av1_check_trailing_bits(pbi, &rb) != 0) {
   823      // cm->error.error_code is already set.
   824      return 0;
   825    }
   826    assert((rb.bit_offset & 7) == 0);
   827    return type_length + (rb.bit_offset >> 3);
   828  }
