   830  // On success, returns 'sz'. On failure, sets pbi->common.error.error_code and
   831  // returns 0.
   832  static size_t read_padding(AV1_COMMON *const cm, const uint8_t *data,
   833                             size_t sz) {
   834    // The spec allows a padding OBU to be header-only (i.e., obu_size = 0). So
   835    // check trailing bits only if sz > 0.
   836    if (sz > 0) {
   837      // The payload of a padding OBU is byte aligned. Therefore the first
   838      // trailing byte should be 0x80. See https://crbug.com/aomedia/2393.
   839      const uint8_t last_nonzero_byte = get_last_nonzero_byte(data, sz);
   840      if (last_nonzero_byte != 0x80) {
   841        cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   842        return 0;
   843      }
   844    }
   845    return sz;
   846  }
